const API_BASE_URL = "http://localhost:8081/api";

// Normal User Login (email/password)
export async function login(email, password) {
  const response = await fetch(`${API_BASE_URL}/auth/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || "Login failed");
  }

  return await response.json();
}

// Admin Login (username/password only)
export async function adminLogin(username, password) {
  const response = await fetch(`${API_BASE_URL}/auth/admin/login`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username, password }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || "Admin login failed");
  }

  return await response.json(); // Must include { username, role: 'admin', ... }
}

// User Signup (default role: DEFAULT_USER)
export async function signup(data) {
  const userPayload = {
    username: data.username,
    email: data.email,
    passwordHash: data.password,
    firstName: "Temp",
    lastName: "User",
    phone: "0000000000",
    role: "DEFAULT_USER", // backend maps to normal user
  };

  const response = await fetch(`${API_BASE_URL}/auth/signup`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(userPayload),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(errorText || "Signup failed");
  }

  return await response.json();
}
